import {FormControl, Select, TextInput} from '@primer/react'
import type {FieldDef} from '../../types'

interface FieldListProps {
  fields: FieldDef[]
  config: Record<string, string>
  onChange: (key: string, value: string) => void
  disabled?: boolean
}

export function FieldList({fields, config, onChange, disabled}: FieldListProps) {
  return (
    <>
      {fields.map(field => {
        const required = field.required !== false
        return (
          <FormControl key={field.key} required={required} disabled={disabled}>
            <FormControl.Label>{field.label}</FormControl.Label>
            {field.options ? (
              <Select value={config[field.key] ?? ''} onChange={e => onChange(field.key, e.target.value)} block>
                {field.options.map(option => (
                  <Select.Option key={option.value} value={option.value}>
                    {option.label}
                  </Select.Option>
                ))}
              </Select>
            ) : (
              <TextInput
                value={config[field.key] ?? ''}
                onChange={e => onChange(field.key, e.target.value)}
                placeholder={field.placeholder}
                block
              />
            )}
          </FormControl>
        )
      })}
    </>
  )
}
