import {App} from './App'
import {TransitionType} from '@github-ui/react-core/app-routing-types'

import {registerNavigatorApp} from '@github-ui/react-core/register-app'

import {jsonRoute} from '@github-ui/react-core/json-route'
import {Index} from './routes/Index/Page'
import {New} from './routes/New/Page'
import {Edit} from './routes/Edit/Page'

// eslint-disable-next-line @github-ui/github-monorepo/prefer-data-router
registerNavigatorApp('actions-data-stream', () => ({
  App,
  routes: [
    // Organization routes
    // eslint-disable-next-line @github-ui/github-monorepo/prefer-data-router
    jsonRoute({
      path: '/organizations/:org/settings/actions/data-stream',
      Component: Index,
      transitionType: TransitionType.FETCH_THEN_TRANSITION,
    }),
    // eslint-disable-next-line @github-ui/github-monorepo/prefer-data-router
    jsonRoute({
      path: '/organizations/:org/settings/actions/data-stream/new',
      Component: New,
      transitionType: TransitionType.FETCH_THEN_TRANSITION,
    }),
    // eslint-disable-next-line @github-ui/github-monorepo/prefer-data-router
    jsonRoute({
      path: '/organizations/:org/settings/actions/data-stream/:id/edit',
      Component: Edit,
      transitionType: TransitionType.FETCH_THEN_TRANSITION,
    }),
    // Enterprise routes
    // eslint-disable-next-line @github-ui/github-monorepo/prefer-data-router
    jsonRoute({
      path: '/enterprises/:business/settings/actions/data-stream',
      Component: Index,
      transitionType: TransitionType.FETCH_THEN_TRANSITION,
    }),
    // eslint-disable-next-line @github-ui/github-monorepo/prefer-data-router
    jsonRoute({
      path: '/enterprises/:business/settings/actions/data-stream/new',
      Component: New,
      transitionType: TransitionType.FETCH_THEN_TRANSITION,
    }),
    // eslint-disable-next-line @github-ui/github-monorepo/prefer-data-router
    jsonRoute({
      path: '/enterprises/:business/settings/actions/data-stream/:id/edit',
      Component: Edit,
      transitionType: TransitionType.FETCH_THEN_TRANSITION,
    }),
  ],
}))
