import {useState, useCallback, useEffect} from 'react'
import {Button, Flash} from '@primer/react'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import type {TestConnectionResult} from '../types'

interface TestConnectionButtonProps {
  testConnectionPath: string
  sinkId?: string
  sinkType?: string
  config?: Record<string, string>
  name?: string
  disabled?: boolean
  size?: 'small' | 'medium' | 'large'
  onTestResult?: (result: TestConnectionResult) => void
}

export function TestConnectionButton({
  testConnectionPath,
  sinkId,
  sinkType,
  config,
  name,
  disabled,
  size = 'medium',
  onTestResult,
}: TestConnectionButtonProps) {
  const [isTesting, setIsTesting] = useState(false)
  const [result, setResult] = useState<TestConnectionResult | null>(null)

  useEffect(() => {
    if (result?.success) {
      const timer = setTimeout(() => setResult(null), 8000)
      return () => clearTimeout(timer)
    }
  }, [result])

  const handleTest = useCallback(async () => {
    if (isTesting) return

    setIsTesting(true)
    setResult(null)

    const body: Record<string, unknown> = {}
    if (sinkId) {
      body.sink_id = sinkId
    } else {
      body.sink_type = sinkType
      body.config = config
      body.name = name || 'test-connection'
    }

    try {
      const response = await verifiedFetchJSON(testConnectionPath, {method: 'POST', body})

      if (response.ok) {
        const data = (await response.json()) as TestConnectionResult
        setResult(data)
        onTestResult?.(data)
      } else {
        const data = (await response.json()) as {success?: boolean; error_message?: string}
        const failResult: TestConnectionResult = {
          success: false,
          error_message: data?.error_message ?? 'Something went wrong. Please try again.',
          status_code: 0,
          latency_ms: 0,
        }
        setResult(failResult)
        onTestResult?.(failResult)
      }
    } catch {
      const failResult: TestConnectionResult = {
        success: false,
        error_message: 'Something went wrong. Please try again.',
        status_code: 0,
        latency_ms: 0,
      }
      setResult(failResult)
      onTestResult?.(failResult)
    } finally {
      setIsTesting(false)
    }
  }, [isTesting, sinkId, sinkType, config, name, testConnectionPath, onTestResult])

  return (
    <div>
      <Button type="button" onClick={handleTest} disabled={disabled || isTesting} size={size}>
        {isTesting ? 'Testing…' : 'Test connection'}
      </Button>
      {result && (
        <Flash variant={result.success ? 'success' : 'danger'} className="tmp-mt-2">
          {result.success ? (
            <span>Connection successful ({result.latency_ms}ms)</span>
          ) : (
            <span>
              <span>Connection failed</span>
              {result.error_message ? <span>: {result.error_message}</span> : null}
              {result.latency_ms > 0 && <span> ({result.latency_ms}ms)</span>}
            </span>
          )}
        </Flash>
      )}
    </div>
  )
}
